'use strict';
const $ = id => document.getElementById(id);
let chosen, retryAction, busy = false;
function status(message) { $('status').textContent = message; }
function readSaved() { try { const data = JSON.parse(localStorage.getItem('claro-favorites') || '[]'); return Array.isArray(data) ? data.filter(x => x && typeof x.name === 'string' && Number.isFinite(x.latitude) && Number.isFinite(x.longitude)).slice(0,20) : []; } catch { return []; } }
function writeSaved(data) { try { localStorage.setItem('claro-favorites', JSON.stringify(data)); renderSaved(); } catch { status('El navegador no permite guardar preferencias. Puedes seguir consultando el clima.'); } }
function renderSaved() { const target = $('saved'); target.replaceChildren(); const list = readSaved(); if (!list.length) { target.textContent = 'Aún no guardas ciudades. Consulta una y selecciona “Guardar ciudad”.'; return; } list.forEach(location => { const button = document.createElement('button'); button.textContent = location.name + ' ↗'; button.addEventListener('click', () => loadWeather(location)); target.append(button); }); }
async function request(url) { const controller = new AbortController(); const timer = setTimeout(() => controller.abort(), 12000); try { const response = await fetch(url, {signal:controller.signal}); if (response.status === 429) throw new Error('Se alcanzó el límite de consultas. Espera un momento y vuelve a intentar.'); if (!response.ok) throw new Error('El proveedor no pudo completar la consulta. Intenta más tarde.'); const data = await response.json(); if (data.error) throw new Error('El proveedor rechazó la consulta. Vuelve a intentar.'); return data; } catch (error) { if (error.name === 'AbortError') throw new Error('La consulta tardó demasiado. Revisa tu conexión y reintenta.'); if (error instanceof TypeError) throw new Error('No se pudo conectar con el servicio. Revisa tu conexión a internet.'); throw error; } finally { clearTimeout(timer); } }
async function run(action) { if (busy) return; busy = true; retryAction = action; $('retry').hidden = true; $('search').querySelector('button').disabled = true; $('result').hidden = true; $('locations').replaceChildren(); status('Consultando el cielo…'); try { await action(); } catch (error) { status(error.message || 'Ocurrió un error inesperado. Vuelve a intentar.'); $('retry').hidden = false; } finally { busy = false; $('search').querySelector('button').disabled = false; } }
function description(code) { if (code === 0) return 'Cielo despejado'; if (code <= 3) return 'Parcialmente nublado'; if ([45,48].includes(code)) return 'Niebla'; if (code >= 51 && code <= 67) return 'Lluvia o llovizna'; if (code >= 71 && code <= 77) return 'Nieve'; if (code >= 80 && code <= 82) return 'Chubascos'; if (code >= 85 && code <= 86) return 'Chubascos de nieve'; if (code >= 95) return 'Tormenta'; return 'Condiciones variables'; }
const number = (value, suffix) => Number.isFinite(value) ? Math.round(value) + suffix : 'Sin datos';
function loadWeather(location) { return run(async () => { const params = new URLSearchParams({latitude:location.latitude,longitude:location.longitude,current:'temperature_2m,relative_humidity_2m,apparent_temperature,weather_code,wind_speed_10m',daily:'weather_code,temperature_2m_max,temperature_2m_min,precipitation_probability_max',timezone:'auto',forecast_days:'7'}); const data = await request('https://api.open-meteo.com/v1/forecast?' + params); if (!data.current || !Number.isFinite(data.current.temperature_2m) || !data.daily?.time?.length) throw new Error('El proveedor devolvió una respuesta vacía o incompleta.'); chosen = location; const c = data.current; $('place').textContent = location.name; $('temperature').textContent = number(c.temperature_2m,'°'); $('condition').textContent = description(c.weather_code); $('feels').textContent = number(c.apparent_temperature,' °C'); $('humidity').textContent = number(c.relative_humidity_2m,' %'); $('wind').textContent = number(c.wind_speed_10m,' km/h'); $('updated').textContent = c.time.replace('T',' · '); $('forecast').replaceChildren(); data.daily.time.forEach((date,i) => { const card = document.createElement('article'); card.className = 'day'; const day = document.createElement('div'); day.textContent = new Date(date + 'T12:00:00').toLocaleDateString('es-MX',{weekday:'short',day:'numeric'}); const temp = document.createElement('strong'); temp.textContent = number(data.daily.temperature_2m_max?.[i],'°') + ' / ' + number(data.daily.temperature_2m_min?.[i],'°'); const label = document.createElement('span'); label.textContent = description(data.daily.weather_code?.[i]); const rain = document.createElement('span'); rain.textContent = 'Lluvia: ' + number(data.daily.precipitation_probability_max?.[i],'%'); card.append(day,temp,label,rain); $('forecast').append(card); }); $('result').hidden = false; status('Pronóstico recibido · Zona horaria: ' + data.timezone); }); }
$('search').addEventListener('submit', event => { event.preventDefault(); const query = $('city').value.trim(); if (query.length < 2) { status('Escribe al menos dos caracteres.'); return; } run(async () => { const data = await request('https://geocoding-api.open-meteo.com/v1/search?' + new URLSearchParams({name:query,count:'6',language:'es',format:'json'})); if (!data.results?.length) { status('No encontramos esa ciudad. Revisa el nombre o prueba una ciudad cercana.'); return; } status('Selecciona la ubicación que buscas:'); data.results.forEach(item => { const location = {name:[item.name,item.admin1,item.country].filter(Boolean).join(', '),latitude:item.latitude,longitude:item.longitude}; const button = document.createElement('button'); button.textContent = location.name; button.addEventListener('click', () => loadWeather(location)); $('locations').append(button); }); }); $('consulta').scrollIntoView({block:'start'}); });
$('retry').addEventListener('click', () => retryAction && run(retryAction));
$('save').addEventListener('click', () => { if (!chosen) return; const list = readSaved(); if (!list.some(x => x.latitude === chosen.latitude && x.longitude === chosen.longitude)) { writeSaved([...list,chosen].slice(-20)); status('Ciudad guardada en este navegador.'); } else status('Esta ciudad ya está en tus favoritas.'); });
$('clear').addEventListener('click', () => { writeSaved([]); status('Se borraron las ciudades favoritas.'); });
document.querySelectorAll('[data-legal]').forEach(button => button.addEventListener('click', () => { const privacy = button.dataset.legal === 'privacy'; $('legal-title').textContent = privacy ? 'Privacidad del prototipo' : 'Condiciones de uso del prototipo'; $('legal-text').textContent = privacy ? 'Este proyecto académico guarda tus ciudades favoritas en localStorage de este navegador. Puedes borrarlas desde Mis ciudades. No incluye analítica, publicidad ni cookies propias. Las consultas envían la ciudad o coordenadas a Open-Meteo; ese proveedor recibe también los datos de conexión necesarios, como la dirección IP. No se solicitan cuentas ni contraseñas. Antes de un lanzamiento público, el responsable deberá incorporar su identidad y contacto y revisar estas condiciones.' : 'Servicio académico para consultar pronósticos orientativos, sujeto a disponibilidad de Open-Meteo. Los datos pueden cambiar y no garantizan condiciones futuras. No sustituye los avisos meteorológicos oficiales. No hay ventas, pagos ni garantías comerciales. Datos atribuidos a Open-Meteo. Estas condiciones describen el prototipo y requieren revisión antes de un uso público.'; $('legal').showModal(); }));
renderSaved();
